                if type(value) is not int or value < 0:
                    raise ValueError(label + " must be a nonnegative integer")
            if sku in seen:
                raise ValueError("duplicate sku in reprice: " + sku)
            seen.add(sku)
            requested.append((sku, expected_price, target_price))
